import{_ as t,o as s,c as e,a5 as d}from"./chunks/framework.CslsFoWx.js";const g=JSON.parse('{"title":"Conformité fiscale","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/15-fiscal-compliance.md","filePath":"generated/modules/15-fiscal-compliance.md","lastUpdated":null}'),n={name:"modules/15-fiscal-compliance.md"};function r(i,a,o,l,p,c){return s(),e("div",null,[...a[0]||(a[0]=[d('<h1 id="conformite-fiscale" tabindex="-1">Conformité fiscale <a class="header-anchor" href="#conformite-fiscale" aria-label="Permalink to &quot;Conformité fiscale&quot;">​</a></h1><p><span class="badge partial">Partiel</span> <span class="muted">Phase 1–2 · <a href="/VendoraSystem-docs/specs/15-fiscal-compliance">spécification complète</a></span></p><p>Module fiscal pluggable par pays qui scelle, archive et transmet sans jamais toucher au flux de vente. Le socle commun et le volet France sont livrés : ventes scellées et chaînées hors ligne, revérification serveur, clôtures J/M/A avec total perpétuel, mode formation, archive en format ouvert, JET, attestation PDF. Le volet Tunisie NACEF, la certification NF525, l&#39;attestation à valeur légale et le hook e-reporting sont bloqués par des actions extérieures.</p><div class="kpis"><div><b>9</b><span>faites</span></div><div><b>5</b><span>partielles</span></div><div><b>2</b><span>à faire</span></div><div><b>9</b><span>bloquées</span></div></div><h2 id="socle-commun" tabindex="-1">Socle commun <a class="header-anchor" href="#socle-commun" aria-label="Permalink to &quot;Socle commun&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Module fiscal par pays verrouillé</strong><br><span class="muted">Le module FR, TN ou NONE est déterminé pour le magasin et devient immuable dès la première vente réelle (409 FISCAL_LOCKED).<br><i>Pays déduit de la devise (fiscal_config.country_code) au lieu de Store.countryCode, API scopée /stores/{id}/fiscal/... : écarts à acter dans la spec 15.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-01, RG-FISC-02</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a></td></tr><tr><td><strong>Scellement chaîné des ventes</strong><br><span class="muted">Chaque vente réelle reçoit hors ligne un numéro fiscal sans trou par appareil et une empreinte SHA-256 chaînée à la précédente.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-FISC-04, RG-FISC-05</td><td>1.x, 2.10, 2.28</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-appairage-ios">📷</a></td></tr><tr><td><strong>Zone fiscale du ticket</strong><br><span class="muted">Le ticket affiche le numéro fiscal et l&#39;empreinte abrégée, et la caisse confirme « Vente scellée — n° fiscal N ».</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td>RG-FISC-05</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-ios">📷</a></td></tr><tr><td><strong>Revérification serveur au push</strong><br><span class="muted">Le serveur revérifie l&#39;empreinte, la continuité par appareil et rejoue le moteur partagé ; une anomalie est signalée, jamais réécrite.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-05, RG-FISC-12</td><td>1.x, 2.20</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-android">📷</a></td></tr><tr><td><strong>Corrections en plus ou en moins</strong><br><span class="muted">Une erreur se corrige par une annulation ou un retour motivé, scellé et chaîné, référençant la vente d&#39;origine.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-03</td><td>2.20, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-annulations-retours">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a></td></tr><tr><td><strong>Clôtures journalières, mensuelles, annuelles</strong><br><span class="muted">Le serveur génère automatiquement les clôtures J/M/A, y compris « néant », chaînées par niveau.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-06, RG-FISC-08</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a></td></tr><tr><td><strong>Total perpétuel</strong><br><span class="muted">Chaque clôture embarque un total perpétuel depuis la première vente réelle, jamais remis à zéro ni purgé.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-07</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a></td></tr><tr><td><strong>Export PDF des clôtures</strong><br><span class="muted">Le gérant télécharge le registre des clôtures en PDF, avec totaux de période, perpétuel et empreintes.<br><i>Le PDF d&#39;une clôture individuelle avec le détail des Z agrégés n&#39;est pas fait.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-06</td><td>2.19</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-export-pdf-z">📷</a></td></tr><tr><td><strong>Mode formation factice</strong><br><span class="muted">Sous PIN manager, une caisse passe en formation : bandeau permanent, tickets « FACTICE - FORMATION », ventes exclues de tous les totaux réels.<br><i>Le refus « Clôturez la session » n&#39;apparaît qu&#39;après la saisie du PIN (pré-contrôle à faire) ; activation depuis l&#39;appareil seulement, le back-office liste les caisses en formation.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-09</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-formation-android">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-formation-ios">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a></td></tr><tr><td><strong>Archive fiscale en format ouvert</strong><br><span class="muted">Le propriétaire génère et télécharge pour une période close un ZIP de CSV avec notice en français et manifeste d&#39;empreintes chaîné.<br><i>09/11 : <code>POST …/fiscal/archives</code> → 202 et statut PENDING → READY / FAILED (JET ARCHIVE_FAILED), reprise au redémarrage, téléchargement refusé (409) tant que l&#39;archive n&#39;est pas prête ; back-office FR / EN / AR ; V87.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-10</td><td>1.x, cartes-09/11</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-09-archive-asynchrone-purge">📷</a></td></tr><tr><td><strong>Conservation au moins 6 ans</strong><br><span class="muted">Les données fiscales sont conservées au moins 6 ans côté serveur ; au-delà, le détail n&#39;est purgé que sous une archive scellée, de façon tracée.<br><i>09/11 : purge du détail de plus de 6 ans seulement si une archive scellée couvre la période (empreintes revérifiées), registre des purges et JET PURGE ; clôtures, total perpétuel et Z intacts ; désactivée par défaut, <code>POS_FISCAL_PURGE_ENABLED=true</code> en production.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-FISC-13, RG-FISC-11</td><td>1.x, cartes-09/11</td><td><a href="/VendoraSystem-docs/preuves/2026-11-09-archive-asynchrone-purge">📷</a></td></tr><tr><td><strong>Journal des événements techniques (JET)</strong><br><span class="muted">Le JET append-only trace ruptures de chaîne, mode formation, verrouillage de configuration, archives, annulations et retours.<br><i>09/11 : types ARCHIVE_FAILED et PURGE émis. Les types APP_UPDATED (mise à jour de version) et CLOCK_SUSPECT (horloge suspecte) ne sont pas émis.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-11</td><td>1.x, 2.20, cartes-09/11</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-11-09-archive-asynchrone-purge">📷</a></td></tr><tr><td><strong>Rapport d&#39;intégrité et alertes</strong><br><span class="muted">Le gérant consulte l&#39;intégrité des chaînes et voit les anomalies de scellement dans les alertes du tableau de bord.</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-12</td><td>1.x, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-reliquats-caisse">📷</a></td></tr><tr><td><strong>Signature des lots push vérifiée par le serveur</strong><br><span class="muted">Les événements poussés sont signés Ed25519 par l&#39;appareil et la signature est vérifiée et conservée par le serveur.<br><i>Identité Ed25519 par appareil faite (lot 2.28, signature sur le LAN) ; la vérification des lots push côté serveur (event_log.signature) reste à faire.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td></td><td>2.28</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-identite-appareil">📷</a></td></tr></tbody></table><h2 id="volet-france" tabindex="-1">Volet France <a class="header-anchor" href="#volet-france" aria-label="Permalink to &quot;Volet France&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Attestation individuelle nominative</strong><br><span class="muted">Le propriétaire télécharge en un clic une attestation PDF conforme au modèle BOI-LETTRE-000242 pour sa version majeure.<br><i>PDF généré avec registre, mais marqué « MODÈLE » sans valeur légale tant que l&#39;identité de l&#39;éditeur (nom du produit et société) n&#39;est pas décidée.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge na">—</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-FISC-21, RG-FISC-23</td><td>1.x</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-fiscal-web">📷</a></td></tr><tr><td><strong>Dossier de certification NF525 / LNE</strong><br><span class="muted">Le dossier de certification (matrice des exigences ISCA, jeux de preuve, procédures) est préparé pour un organisme accrédité.<br><i>Non fait ; dépend d&#39;un organisme accrédité, visé avant toute commercialisation en France.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-FISC-20, RG-FISC-22</td><td></td><td></td></tr><tr><td><strong>Hook e-reporting B2C</strong><br><span class="muted">Le module FR fournit les agrégats journaliers de TVA issus des clôtures pour la transmission via une plateforme agréée.<br><i>Lot 3.15 (05/11/2026) : agrégats lus dans les lignes de vente (même source que les clôtures journalières, scellement du jour indiqué), connecteur EReportingPlatform côté serveur avec plateforme simulée ; les vraies plateformes se branchent avec leurs clés (action terrain).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-FISC-24</td><td>3.15</td><td><a href="/VendoraSystem-docs/preuves/2026-11-05-315-e-reporting">📷</a></td></tr></tbody></table><h2 id="volet-tunisie-nacef" tabindex="-1">Volet Tunisie (NACEF) <a class="header-anchor" href="#volet-tunisie-nacef" aria-label="Permalink to &quot;Volet Tunisie (NACEF)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Module de sécurisation fiscale</strong><br><span class="muted">Le module TN assure le stockage local inviolable et la sécurisation cryptographique des ventes avant transmission.<br><i>Règle provisoire : attend le cahier des charges NACEF (site géo-bloqué) ; hypothèse « module logiciel » à valider.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-FISC-30</td><td></td><td></td></tr><tr><td><strong>QR code fiscal sur le ticket</strong><br><span class="muted">Chaque ticket réel d&#39;un magasin tunisien porte un QR fiscal vérifiable ; un ticket de formation porte « FACTICE » à la place.<br><i>Contenu du QR à caler sur le cahier des charges NACEF.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-FISC-31</td><td></td><td></td></tr><tr><td><strong>Mentions obligatoires du ticket TN</strong><br><span class="muted">La zone fiscale tunisienne affiche l&#39;identifiant du module, le matricule fiscal, le numéro fiscal, la TVA par taux et les modes de paiement.<br><i>Règle provisoire, attend le cahier des charges NACEF.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-FISC-32</td><td></td><td></td></tr><tr><td><strong>Transmission quasi temps réel à NACEF</strong><br><span class="muted">Chaque vente scellée et chaque clôture journalière partent vers NACEF de façon asynchrone, avec accusé de réception.<br><i>Protocole, format et endpoint inconnus tant que le cahier des charges NACEF n&#39;est pas récupéré.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-FISC-33</td><td></td><td></td></tr><tr><td><strong>File de retransmission fiscale</strong><br><span class="muted">Une file fiscal_outbox retransmet dans l&#39;ordre et sans doublon après une coupure, avec alerte et pastille d&#39;état en caisse.<br><i>Réutilisera la mécanique d&#39;outbox existante ; bloqué avec la transmission NACEF.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-FISC-34</td><td></td><td></td></tr><tr><td><strong>Calendrier d&#39;obligation</strong><br><span class="muted">Le module TN s&#39;active pour les magasins de profil restaurant et le back-office informe du calendrier légal.<br><i>Dépend du volet NACEF.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-FISC-35, RG-FISC-36</td><td></td><td></td></tr><tr><td><strong>Homologation fournisseur NACEF</strong><br><span class="muted">L&#39;éditeur obtient l&#39;accréditation fournisseur et l&#39;homologation de la caisse auprès du ministère des Finances.<br><i>Actions terrain : inscription NACEF depuis une connexion tunisienne, appel DGI ; dépend aussi du nom du produit et de la société.</i></span></td><td><span class="badge blocked">Bloqué (terrain)</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-FISC-38</td><td></td><td></td></tr><tr><td><strong>Hook El Fatoora (TEIF / TTN)</strong><br><span class="muted">Le module TN exporte les factures au format TEIF signé via TTN pour les clients assujettis.<br><i>Phase 4 (spec 12, AMEL-10).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-FISC-37</td><td></td><td></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>Volet Tunisie NACEF complet (sécurisation, QR fiscal, mentions, transmission, fiscal_outbox, homologation) : bloqué par le cahier des charges.</li><li>Attestation FR à valeur légale : bloquée par l&#39;identité de l&#39;éditeur (nom du produit et société).</li><li>Dossier de certification NF525 / LNE et hook e-reporting B2C (spec 12, plateforme agréée).</li><li>PDF d&#39;une clôture individuelle ; types JET APP_UPDATED et CLOCK_SUSPECT.</li><li>Mode formation : pré-contrôle « clôturez la session » avant la saisie du PIN.</li><li>Signature Ed25519 des lots push vérifiée par le serveur (event_log.signature).</li><li>Acter dans la spec 15 l&#39;API scopée /stores/{id}/fiscal/... et fiscal_config.country_code.</li><li>El Fatoora (TEIF / TTN) en phase 4.</li></ul>',12)])])}const b=t(n,[["render",r]]);export{g as __pageData,b as default};
